using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Tools -----------------------------------------------------------

var notepad = new ResearchNotepad();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
        {
            Console.WriteLine($"  🔍 Searching: \"{query}\"");
            return WebSearchSimulator.Search(query);
        },
        "web_search",
        "Searches the web for information on a topic. Returns a list of result snippets."),

    AIFunctionFactory.Create(
        (
            [Description("Short title for the note")] string title,
            [Description("Content of the note")] string content
        ) =>
        {
            notepad.Add(title, content);
            Console.WriteLine($"  📝 Note saved: \"{title}\"");
            return $"Note '{title}' saved successfully.";
        },
        "save_note",
        "Saves a research note for later use in the summary."),

    AIFunctionFactory.Create(
        () =>
        {
            var notes = notepad.GetAll();
            Console.WriteLine($"  📖 Reading {notes.Count} note(s)");
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "read_notes",
        "Reads all previously saved research notes."),
};

// --- Agent -----------------------------------------------------------

IChatClient chatClient = new OpenAIChatClient(
    new OpenAI.Chat.ChatClient(modelId, apiKey));

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI research assistant that searches the web and takes notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    });

// --- Run -------------------------------------------------------------

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2025";

Console.WriteLine($"🔬 Research Agent Starting...\n");
Console.WriteLine($"📋 Topic: {topic}\n");

var prompt = $"""
    You are a research assistant. Your goal is to thoroughly research the following topic
    and produce a well-organized summary.

    Topic: {topic}

    Instructions:
    1. Use the web_search tool multiple times with different queries to gather information.
    2. After each search, use save_note to record the key findings.
    3. Once you have gathered enough information (at least 3 searches), use read_notes
       to review everything you have collected.
    4. Finally, produce a comprehensive summary of your research findings, citing
       the sources where applicable.
    """;

var session = await agent.CreateSessionAsync("research");

var response = await agent.RunAsync(
    prompt,
    session,
    new ChatClientAgentRunOptions(new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    }));

Console.WriteLine("\n" + new string('═', 60));
Console.WriteLine("📄 RESEARCH SUMMARY");
Console.WriteLine(new string('═', 60) + "\n");

foreach (var message in response.Messages.Where(m => m.Role == ChatRole.Assistant))
{
    var text = message.Text;
    if (!string.IsNullOrWhiteSpace(text))
    {
        Console.WriteLine(text);
    }
}

Console.WriteLine($"\n📝 Total notes collected: {notepad.GetAll().Count}");

// --- Supporting types ------------------------------------------------

/// <summary>Simple in-memory notepad for the agent to store research findings.</summary>
sealed class ResearchNotepad
{
    private readonly List<Note> _notes = [];

    public void Add(string title, string content) => _notes.Add(new(title, content));
    public IReadOnlyList<Note> GetAll() => _notes;

    public record Note(string Title, string Content);
}

/// <summary>Simulated web search that returns canned results for demonstration.</summary>
static class WebSearchSimulator
{
    public static string Search(string query)
    {
        var q = query.ToLowerInvariant();

        // Return plausible search results based on keyword matching.
        List<SearchResult> results =
        [
            new($"Overview of {query} - Wikipedia",
                $"A comprehensive overview of {query}. This topic has seen significant developments in recent years, "
                + "with researchers and industry leaders making notable progress across multiple fronts.",
                $"https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}"),

            new($"{query} - Latest Research and Developments",
                $"Recent studies and breakthroughs related to {query} have been published in leading journals. "
                + "Key areas of focus include practical applications, theoretical foundations, and emerging challenges.",
                $"https://research.example.com/{Uri.EscapeDataString(query)}"),

            new($"Expert Analysis: The Future of {query}",
                $"Industry experts predict that {query} will continue to evolve rapidly. "
                + "Major tech companies and research institutions are investing heavily in this area, "
                + "with potential impacts on healthcare, finance, and communications.",
                $"https://techreview.example.com/future-{Uri.EscapeDataString(query)}"),
        ];

        if (q.Contains("quantum"))
        {
            results.Add(new("Quantum Computing Milestone: 1000-Qubit Processor",
                "Researchers have achieved a major milestone with a 1000-qubit quantum processor "
                + "demonstrating error-corrected operations. This breakthrough brings practical "
                + "quantum advantage closer to reality for optimization and simulation tasks.",
                "https://quantumnews.example.com/1000-qubit"));

            results.Add(new("Quantum Error Correction Advances",
                "New error correction codes have reduced the overhead needed for fault-tolerant "
                + "quantum computing by 10x, making near-term quantum applications more feasible.",
                "https://arxiv.example.com/quantum-error-correction"));
        }

        if (q.Contains("ai") || q.Contains("artificial intelligence") || q.Contains("machine learning"))
        {
            results.Add(new("State of AI Report 2025",
                "AI systems have achieved human-level performance on a wider range of benchmarks. "
                + "Multimodal models now handle text, images, audio, and video with unprecedented accuracy.",
                "https://stateofai.example.com/2025"));
        }

        return string.Join("\n\n", results.Select((r, i) =>
            $"[{i + 1}] {r.Title}\n    {r.Snippet}\n    Source: {r.Url}"));
    }

    private record SearchResult(string Title, string Snippet, string Url);
}

